package com.atlashub.pay.ledger.application.queries.GetFinancialAccount;import com.atlashub.pay.ledger.application.queries.FinancialAccountResults.FinancialAccountResult;import com.atlashub.pay.ledger.application.queries.ListFinancialAccounts.*;import com.atlashub.pay.ledger.domain.exceptions.LedgerAccountNotFoundException;import com.atlashub.shared.application.usecase.Query;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Component;@Component public class GetFinancialAccountHandler extends Query<GetFinancialAccountQuery,FinancialAccountResult>{private final ListFinancialAccountsHandler list;public GetFinancialAccountHandler(ListFinancialAccountsHandler l){list=l;}@Override @PreAuthorize("hasAuthority('pay:ledger:read')")public FinancialAccountResult execute(GetFinancialAccountQuery q){return list.execute(new ListFinancialAccountsQuery(q.organizationId(),q.environment())).stream().filter(a->a.id().equals(q.accountId())).findFirst().orElseThrow(()->new LedgerAccountNotFoundException(q.accountId().toString()));}}
